     "title": "LDL cholesterol or ApoB above the guideline",
     "when": [
      "high"
     ],
     "why": "LDL cholesterol causes atherosclerosis and ApoB counts its particles; how far to lower them depends on the whole risk (ESC/EAS 2019 and the 2025 focused update)."
    },
    {
     "groups": [
      "lpa"
     ],
     "id": "lpa",
     "questions": [
      "family-cvd",
      "family-lipids",
      "relatives-lpa"
     ],
     "risks": [
      "cardiovascular"
     ],
     "title": "Lp(a) raised or above the lab's limit",
     "when": [
      "high",
      "at_limit",
      "lab_high"
     ],
     "why": "Lp(a) is mostly inherited and changes little over life; raised Lp(a) adds to the risk from LDL, and close relatives should be tested (ESC/EAS 2025; EAS consensus 2022)."
    },
    {
     "groups": [
      "tg"
